<?php
declare(strict_types=1);
use App\Core\Auth;use App\Core\Csrf;use App\Core\Env;
define('BASE_PATH',dirname(__DIR__));spl_autoload_register(static function(string $class):void{if(!str_starts_with($class,'App\\'))return;$file=BASE_PATH.'/app/'.str_replace('\\','/',substr($class,4)).'.php';if(is_file($file))require $file;});Env::load(BASE_PATH.'/.env');if(session_status()!==PHP_SESSION_ACTIVE){session_name('veelox_portal');session_set_cookie_params(['httponly'=>true,'secure'=>isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Lax','path'=>'/']);session_start();}if(!Auth::check()){header('Location: /login');exit;}if((Auth::user()['role']??'')!=='admin'){http_response_code(403);exit('Administrator access is required.');}
$envPath=BASE_PATH.'/.env';$errors=[];$saved=false;function mailEnvQuote(string $value):string{return '"'.str_replace(['\\','"'],['\\\\','\\"'],str_replace(["\r","\n"],'',$value)).'"';}function mailUpdateEnv(string $source,string $key,string $value):string{$line=$key.'='.mailEnvQuote($value);$pattern='/^'.preg_quote($key,'/').'=.*$/m';return preg_match($pattern,$source)?(string)preg_replace($pattern,$line,$source):rtrim($source).PHP_EOL.$line.PHP_EOL;}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_token']??null))$errors[]='Your session expired.';else{$host=trim((string)($_POST['host']??''));$port=(int)($_POST['port']??587);$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$from=trim((string)($_POST['from_address']??''));$fromName=trim((string)($_POST['from_name']??'Veelox Digital'));$encryption=in_array($_POST['encryption']??'', ['tls','ssl',''],true)?$_POST['encryption']:'tls';if(!$host||!$port||!filter_var($from,FILTER_VALIDATE_EMAIL))$errors[]='Host, port and a valid from address are required.';if(!$errors){$source=(string)file_get_contents($envPath);foreach(['MAIL_HOST'=>$host,'MAIL_PORT'=>(string)$port,'MAIL_USERNAME'=>$username,'MAIL_FROM_ADDRESS'=>$from,'MAIL_FROM_NAME'=>$fromName,'MAIL_ENCRYPTION'=>$encryption] as $key=>$value)$source=mailUpdateEnv($source,$key,$value);if($password!=='')$source=mailUpdateEnv($source,'MAIL_PASSWORD',$password);if(file_put_contents($envPath,$source,LOCK_EX)===false)$errors[]='The .env file is not writable.';else $saved=true;}}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SMTP setup · Veelox Digital</title><style>:root{--ink:#18202b;--muted:#697386;--line:#e4e7ed;--violet:#7357eb}*{box-sizing:border-box}body{margin:0;padding:30px;background:#f4f5f8;color:var(--ink);font-family:Arial,sans-serif}.card{width:min(720px,100%);margin:auto;padding:38px;background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:0 20px 60px #0001}h1{margin:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:25px}label{font-size:11px;font-weight:700}input,select{display:block;width:100%;margin-top:7px;padding:12px;border:1px solid var(--line);border-radius:9px}.wide{grid-column:1/-1}.notice{margin:18px 0;padding:13px;border-radius:9px;background:#eaf9f2;color:#267253}.error{background:#fff0f0;color:#a53f3f}button,.button{display:inline-flex;margin-top:22px;padding:12px 17px;border:0;border-radius:9px;background:var(--violet);color:#fff;text-decoration:none;font-weight:700}.button{margin-left:8px;background:#efedf8;color:#5c49b2}@media(max-width:600px){.card{padding:25px}.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><main class="card"><p style="color:var(--violet);font-weight:800">VEELOX DIGITAL</p><h1>SMTP settings</h1><p style="color:var(--muted)">Use the mailbox details supplied by DirectAdmin. Leave password blank to preserve it.</p><?php if($saved): ?><div class="notice">SMTP settings saved. Use Email Centre to send a test.</div><?php endif; ?><?php if($errors): ?><div class="notice error"><?= implode('<br>',array_map('htmlspecialchars',$errors)) ?></div><?php endif; ?><form method="post"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>"><div class="grid"><label>SMTP host<input name="host" value="<?= htmlspecialchars((string)Env::get('MAIL_HOST','')) ?>" required></label><label>Port<input type="number" name="port" value="<?= (int)Env::get('MAIL_PORT','587') ?>" required></label><label>Username<input name="username" value="<?= htmlspecialchars((string)Env::get('MAIL_USERNAME','')) ?>"></label><label>Password<input type="password" name="password" autocomplete="new-password" placeholder="Leave blank to keep current"></label><label>Encryption<select name="encryption"><option value="tls">STARTTLS</option><option value="ssl">SSL/TLS</option><option value="">None</option></select></label><label>From name<input name="from_name" value="<?= htmlspecialchars((string)Env::get('MAIL_FROM_NAME','Veelox Digital')) ?>"></label><label class="wide">From email<input type="email" name="from_address" value="<?= htmlspecialchars((string)Env::get('MAIL_FROM_ADDRESS','')) ?>" required></label></div><button>Save SMTP settings</button><a class="button" href="/emails">Email Centre</a></form></main></body></html>
